public class DatasetUtilities_iterateRangeBounds_TriageGen1Test {

    @Test
    public void testStandardXYDataset_Basic() {
        XYDataset mockDataset = mock(XYDataset.class);
        when(mockDataset.getSeriesCount()).thenReturn(1);
        when(mockDataset.getItemCount(0)).thenReturn(2);
        when(mockDataset.getYValue(0, 0)).thenReturn(10.0);
        when(mockDataset.getYValue(0, 1)).thenReturn(20.0);

        Range result = DatasetUtilities.iterateRangeBounds(mockDataset, false);
        assertNotNull(result);
        assertEquals(10.0, result.getLower(), 1e-9);
        assertEquals(20.0, result.getUpper(), 1e-9);
    }

    @Test
    public void testStandardXYDataset_WithNaN() {
        XYDataset mockDataset = mock(XYDataset.class);
        when(mockDataset.getSeriesCount()).thenReturn(1);
        when(mockDataset.getItemCount(0)).thenReturn(3);
        when(mockDataset.getYValue(0, 0)).thenReturn(Double.NaN);
        when(mockDataset.getYValue(0, 1)).thenReturn(5.0);
        when(mockDataset.getYValue(0, 2)).thenReturn(15.0);

        Range result = DatasetUtilities.iterateRangeBounds(mockDataset, false);
        assertNotNull(result);
        assertEquals(5.0, result.getLower(), 1e-9);
        assertEquals(15.0, result.getUpper(), 1e-9);
    }

    @Test
    public void testStandardXYDataset_EmptyOrAllNaN() {
        XYDataset mockDataset = mock(XYDataset.class);
        when(mockDataset.getSeriesCount()).thenReturn(1);
        when(mockDataset.getItemCount(0)).thenReturn(1);
        when(mockDataset.getYValue(0, 0)).thenReturn(Double.NaN);

        Range result = DatasetUtilities.iterateRangeBounds(mockDataset, false);
        assertNull(result);
    }

    @Test
    public void testIntervalXYDataset_IncludeIntervalTrue() {
        // Note: The code uses 'series = 1' as start for IntervalXYDataset loop
        IntervalXYDataset mockDataset = mock(IntervalXYDataset.class);
        when(mockDataset.getSeriesCount()).thenReturn(3); // series 0, 1, 2
        when(mockDataset.getItemCount(1)).thenReturn(1);
        when(mockDataset.getItemCount(2)).thenReturn(1);

        // Series 1
        when(mockDataset.getYValue(1, 0)).thenReturn(10.0);
        when(mockDataset.getStartYValue(1, 0)).thenReturn(5.0);
        when(mockDataset.getEndYValue(1, 0)).thenReturn(15.0);

        // Series 2
        when(mockDataset.getYValue(2, 0)).thenReturn(Double.NaN);
        when(mockDataset.getStartYValue(2, 0)).thenReturn(Double.NaN);
        when(mockDataset.getEndYValue(2, 0)).thenReturn(25.0);

        Range result = DatasetUtilities.iterateRangeBounds(mockDataset, true);
        assertNotNull(result);
        assertEquals(5.0, result.getLower(), 1e-9);
        assertEquals(25.0, result.getUpper(), 1e-9);
    }

    @Test
    public void testIntervalXYDataset_IncludeIntervalFalse_FallsToStandard() {
        // If includeInterval is false, it should use the 'else' block (standard XYDataset logic)
        IntervalXYDataset mockDataset = mock(IntervalXYDataset.class);
        when(mockDataset.getSeriesCount()).thenReturn(1);
        when(mockDataset.getItemCount(0)).thenReturn(1);
        when(mockDataset.getYValue(0, 0)).thenReturn(12.0);

        Range result = DatasetUtilities.iterateRangeBounds(mockDataset, false);
        assertNotNull(result);
        assertEquals(12.0, result.getLower(), 1e-9);
        assertEquals(12.0, result.getUpper(), 1e-9);
    }

    @Test
    public void testOHLCDataset_IncludeIntervalTrue() {
        OHLCDataset mockDataset = mock(OHLCDataset.class);
        when(mockDataset.getSeriesCount()).thenReturn(1);
        when(mockDataset.getItemCount(0)).thenReturn(2);

        // Item 0
        when(mockDataset.getLowValue(0, 0)).thenReturn(10.0);
        when(mockDataset.getHighValue(0, 0)).thenReturn(20.0);

        // Item 1
        when(mockDataset.getLowValue(0, 1)).thenReturn(Double.NaN);
        when(mockDataset.getHighValue(0, 1)).thenReturn(30.0);

        Range result = DatasetUtilities.iterateRangeBounds(mockDataset, true);
        assertNotNull(result);
        assertEquals(10.0, result.getLower(), 1e-9);
        assertEquals(30.0, result.getUpper(), 1e-9);
    }

    @Test
    public void testOHLCDataset_IncludeIntervalFalse_FallsToStandard() {
        OHLCDataset mockDataset = mock(OHLCDataset.class);
        when(mockDataset.getSeriesCount()).thenReturn(1);
        when(mockDataset.getItemCount(0)).thenReturn(1);
        // In standard case, it calls getYValue, not getLow/High
        when(mockDataset.getYValue(0, 0)).thenReturn(15.0);

        Range result = DatasetUtilities.iterateRangeBounds(mockDataset, false);
        assertNotNull(result);
        assertEquals(15.0, result.getLower(), 1e-9);
        assertEquals(15.0, result.getUpper(), 1e-9);
    }

    @Test
    public void testEmptyDataset_ReturnsNull() {
        XYDataset mockDataset = mock(XYDataset.class);
        when(mockDataset.getSeriesCount()).thenReturn(0);

        Range result = DatasetUtilities.iterateRangeBounds(mockDataset, false);
        assertNull(result);
    }
}
